<template><view v-if="issue" class="page"><view class="summary" :class="{major:issue.major}"><view class="top"><view class="status" :class="statusClass(issue.status)">{{issue.status}}</view><view v-if="issue.major" class="major-tag">重大隐患</view><view class="id">{{issue.id}}</view></view><view class="title">{{issue.title}}</view><view class="copy">{{issue.description}}</view><view class="facts"><view><text>责任部门</text>{{issue.assigneeDept||'待安监交办'}}</view><view><text>整改期限</text>{{issue.deadline}}</view><view><text>现场位置</text>{{issue.location}}</view></view></view>
  <view v-if="canAssign && issue.status==='待交办'" class="card"><view class="card-title">安监交办</view><view class="copy">交办后市场营销部仅可处理本部门收到的任务。</view><picker mode="date" :value="assignment.deadline" @change="assignment.deadline=$event.detail.value"><view class="picker">整改期限：{{assignment.deadline}} ›</view></picker><button class="dark" @click="assign">下达市场营销部整改</button></view>
  <view class="section-title">闭环过程</view><view class="timeline"><view v-for="row in issue.audit" :key="row.action+row.time" class="step"><view class="dot"></view><view><view class="step-name">{{row.action}}</view><view class="step-meta">{{row.actor}} · {{row.time}}</view><view class="step-note">{{row.note}}</view></view></view></view>
  <view v-if="canRectify" class="card"><view class="card-title">提交整改佐证</view><textarea v-model="rectification.note" placeholder="填写整改措施、现场情况和无法完成的原因"/><view class="files"><view v-for="item in rectification.attachments" :key="item" class="thumb"><image :src="item" mode="aspectFill"/></view><view class="upload" @click="addPhotos">＋<text>照片</text></view></view><button class="dark" :disabled="!rectification.note" @click="submit">提交安监复核</button></view>
  <view v-if="issue.rectification" class="card evidence"><view class="card-title">整改材料</view><view class="copy">{{issue.rectification.note}}</view><view class="submitted">市场营销部 · {{issue.rectification.submittedAt}}</view></view>
  <view v-if="canReview" class="card review"><view class="card-title">安监复核</view><textarea v-model="reviewNote" placeholder="填写复核意见；退回整改时必填"/><view class="review-actions"><button class="minor" @click="returnIssue">退回整改</button><button class="dark" @click="close">确认复核并闭环</button></view></view>
  <view v-if="!canRectify&&!canReview&&!canAssign" class="read-only">当前为只读视图。你可查看被授权事项的处理进度，但不能提交、退回或闭环。</view></view><view v-else class="empty">未找到该隐患记录</view></template>
<script setup>
import {computed,reactive,ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {demoStore} from '../../stores/demo';import {chooseEvidenceImages} from '../../services/platform';let id='';const issue=computed(()=>demoStore.issues.find(x=>x.id===id));const assignment=reactive({deadline:new Date(Date.now()+7*86400000).toISOString().slice(0,10)}),rectification=reactive({note:'',attachments:[]}),reviewNote=ref('');const canAssign=computed(()=>demoStore.can('issue-assign',issue.value)),canRectify=computed(()=>demoStore.can('issue-rectify',issue.value)),canReview=computed(()=>demoStore.can('issue-review',issue.value));onLoad(o=>{id=o.id});function statusClass(s){return ({'待交办':'draft','待整改':'todo','待复核':'review','已逾期':'overdue','已闭环':'closed'})[s]}function assign(){demoStore.assignIssue(id,{assignee:'市场整改员',assigneeDept:'市场营销部',deadline:assignment.deadline});uni.showToast({title:'已下达交办单',icon:'success'})}async function addPhotos(){try{const r=await chooseEvidenceImages();rectification.attachments.push(...r.tempFilePaths)}catch{}}function submit(){demoStore.submitRectification(id,rectification);uni.showToast({title:'已提交复核',icon:'success'})}function returnIssue(){if(!reviewNote.value){uni.showToast({title:'请填写退回原因',icon:'none'});return}demoStore.returnIssue(id,reviewNote.value);uni.showToast({title:'已退回整改',icon:'success'})}function close(){demoStore.closeIssue(id,reviewNote.value||undefined);uni.showToast({title:'隐患已闭环',icon:'success'})}
</script>
<style lang="scss" scoped>.page{padding:30rpx 28rpx 66rpx;max-width:1040px;margin:auto}.summary,.card{background:#fffcfa;border-radius:22rpx;padding:28rpx;margin-bottom:18rpx;box-shadow:0 8rpx 20rpx rgba(79,49,51,.05)}.summary.major{box-shadow:inset 7rpx 0 #c53a34,0 8rpx 20rpx rgba(79,49,51,.05)}.top,.facts,.review-actions,.files{display:flex;align-items:center}.top{gap:10rpx}.status,.major-tag{font-size:20rpx;padding:5rpx 10rpx;border-radius:7rpx}.draft{background:#ede8e5;color:#655e5b}.todo{background:#fff0e5;color:#995413}.review{background:#edf1fb;color:#3d5b99}.overdue{background:#fff0ee;color:#b62e2b}.closed{background:#edf5ef;color:#287144}.major-tag{background:#f8e8ed;color:#9f2349}.id{margin-left:auto;color:#9d9390;font-size:19rpx}.title{font-size:37rpx;font-weight:750;line-height:1.35;margin:20rpx 0 10rpx}.copy,.step-meta,.step-note,.submitted{font-size:22rpx;color:#756c6b;line-height:1.62}.facts{align-items:stretch;flex-wrap:wrap;gap:12rpx;margin-top:24rpx}.facts view{box-sizing:border-box;flex:1 1 30%;min-width:180rpx;background:#f5f2ef;border-radius:12rpx;padding:16rpx;font-size:22rpx;line-height:1.5}.facts text{display:block;font-size:19rpx;color:#8f8582;margin-bottom:5rpx}.section-title{font-size:32rpx;font-weight:740;margin:40rpx 0 18rpx}.timeline{padding-left:6rpx}.step{display:flex;gap:18rpx;position:relative;padding-bottom:28rpx}.step:not(:last-child)::before{content:'';position:absolute;left:10rpx;top:23rpx;height:calc(100% - 4rpx);width:2rpx;background:#e8dfdc}.dot{width:18rpx;height:18rpx;border-radius:50%;background:#9f2349;margin-top:7rpx;z-index:1}.step-name{font-size:26rpx;font-weight:680}.step-note{margin-top:3rpx}.card-title{font-size:29rpx;font-weight:730;margin-bottom:14rpx}.picker{background:#f5f2ef;padding:18rpx;border-radius:12rpx;margin:20rpx 0;font-size:23rpx}textarea{box-sizing:border-box;width:100%;height:145rpx;background:#f5f2ef;border-radius:12rpx;padding:18rpx;font-size:24rpx}.files{gap:12rpx;flex-wrap:wrap;margin:18rpx 0}.thumb,.upload{width:110rpx;height:110rpx;border-radius:12rpx;overflow:hidden}.thumb image{width:100%;height:100%}.upload{border:1rpx dashed #a99d98;color:#9f2349;display:flex;flex-direction:column;justify-content:center;align-items:center;font-size:38rpx}.upload text{font-size:19rpx}.dark,.minor{font-size:25rpx;border-radius:12rpx;margin:0}.dark{background:#211d1d;color:#fff}.dark[disabled]{background:#b9afab}.evidence{background:#fff8f8}.submitted{margin-top:12rpx}.review-actions{gap:12rpx;margin-top:18rpx}.review-actions button{flex:1}.minor{background:#eee8e5;color:#514946}.read-only{font-size:22rpx;color:#756c6b;line-height:1.65;padding:22rpx;background:#eee8e5;border-radius:14rpx}.empty{text-align:center;padding:100rpx;color:#756c6b}@media(min-width:900px){.page{padding:28px 30px 60px}.summary,.card{padding:28px;border-radius:18px;margin-bottom:14px}.status,.major-tag{font-size:11px}.id{font-size:10px}.title{font-size:30px}.copy,.step-meta,.step-note,.submitted{font-size:13px}.facts{gap:10px;margin-top:20px}.facts view{min-width:0;padding:13px;font-size:13px}.facts text{font-size:11px}.section-title{font-size:25px;margin:34px 0 14px}.step{gap:14px;padding-bottom:22px}.dot{width:10px;height:10px;margin-top:5px}.step:not(:last-child)::before{left:5px;top:14px}.step-name{font-size:15px}.card-title{font-size:18px}.picker{padding:13px;font-size:13px;margin:15px 0}textarea{height:100px;padding:13px;font-size:13px}.thumb,.upload{width:76px;height:76px}.dark,.minor{font-size:13px}.read-only{font-size:13px}}</style>
